-- El recorrido pasa del plano (una foto) al mapa del barrio (OpenStreetMap).
--
-- En el itinerario guardado de Recorrido se quitan el plano y su trazado (que
-- iban en tanto por ciento de la foto) y se pone el recorrido en coordenadas:
-- el de 2025, calcado del plano. Queda sin pegar a las calles; en el CMS se
-- puede redibujar sobre el mapa con «Pegar a las calles».
--
-- Si las paradas siguen siendo las de partida de antes (nueve, del centro
-- histórico, que no son de este recorrido), se cambian por las diecinueve
-- calles del recorrido de 2025, con la hora por confirmar. Si alguien ya las
-- ha editado, se quedan como están.
--
-- JSON_QUERY sobre un texto: así MariaDB lo mete como JSON (con su false) y no
-- como una cadena.

UPDATE `ContenidoPagina` SET `datos` = JSON_SET(JSON_REMOVE(JSON_REMOVE(`datos`, '$.bloques[0].plano'), '$.bloques[0].trazado'),
  '$.bloques[0].recorrido', JSON_QUERY('{"esquinas":[[-4.448709,36.712206],[-4.449203,36.713583],[-4.452188,36.713135],[-4.452264,36.713008],[-4.451894,36.711978],[-4.452459,36.711813],[-4.453866,36.710385],[-4.456021,36.709999],[-4.45601,36.709601],[-4.455875,36.708857],[-4.45574,36.708085],[-4.448396,36.709144],[-4.448058,36.708023],[-4.447286,36.708134],[-4.447512,36.708909],[-4.445788,36.709171],[-4.445773,36.70905],[-4.444955,36.709141],[-4.445105,36.709609],[-4.446899,36.709396],[-4.447053,36.710021],[-4.446598,36.710032],[-4.446478,36.710629],[-4.446872,36.710893],[-4.446855,36.711077],[-4.446457,36.711137],[-4.446769,36.712082],[-4.447166,36.71204],[-4.44729,36.712387],[-4.448709,36.712206]],"linea":[[-4.448709,36.712206],[-4.449203,36.713583],[-4.452188,36.713135],[-4.452264,36.713008],[-4.451894,36.711978],[-4.452459,36.711813],[-4.453866,36.710385],[-4.456021,36.709999],[-4.45601,36.709601],[-4.455875,36.708857],[-4.45574,36.708085],[-4.448396,36.709144],[-4.448058,36.708023],[-4.447286,36.708134],[-4.447512,36.708909],[-4.445788,36.709171],[-4.445773,36.70905],[-4.444955,36.709141],[-4.445105,36.709609],[-4.446899,36.709396],[-4.447053,36.710021],[-4.446598,36.710032],[-4.446478,36.710629],[-4.446872,36.710893],[-4.446855,36.711077],[-4.446457,36.711137],[-4.446769,36.712082],[-4.447166,36.71204],[-4.44729,36.712387],[-4.448709,36.712206]],"pegado":false}', '$'))
WHERE `slug` = 'recorrido' AND JSON_UNQUOTE(JSON_EXTRACT(`datos`, '$.bloques[0].tipo')) = 'itinerario' AND JSON_EXTRACT(`datos`, '$.bloques[0].recorrido') IS NULL;

